\label{thm:framed-congruence}
Let $\mathcal L$ be an oriented link with integer framing vector $\vec\tau$, and let 
$\vec\nu$ be a nonempty partition tuple with total length $\ell(\vec\nu)=r$.  For every $n\ge2$ and every root $\alpha$ with $\operatorname{ord}(\alpha^2)=n$,
\begin{equation}\label{eq:framed-congruence}
 H^{\vec\tau}_{n\vec\nu}-n^{r-1}\Psi_nH^{\vec\tau}_{\vec\nu}
 \in(q-\alpha)^2\mathcal O_\alpha[a^{\pm1}].
\end{equation}

\label{thm:framed-LMOV}
Let $\mathcal L$ be an oriented link with integer framing vector $\vec\tau$.  For every nonempty tuple of partitions $\vec A$,
\begin{equation}\label{eq:intro-framed}
 vP^{\vec\tau}_{\vec A}(q,a)\in\mathbb Z[v,a^{\pm1}].
\end{equation}
Equivalently,
\begin{equation}\label{eq:intro-framed-expansion}
 P^{\vec\tau}_{\vec A}(q,a)
 =\sum_{g\ge0}\sum_{Q\in\mathbb Z}
 N^{\vec\tau}_{\vec A;g,Q}\,z^{2g-2}a^Q,
\end{equation}
where the coefficients are integers and only finitely many terms are nonzero for fixed $\mathcal L,\vec\tau,\vec A$.

\label{lem:framed-parallel}
Suppose the parts \(m_1,\ldots,m_s\) belong to one original component with integer framing \(\tau\). The corresponding signed $q$-framed moment is
\[
(-a^{-1})^{\tau(m_1+\cdots+m_s)}
\]
times the ordinary framed skein evaluation of the \(s\) parallel curves in the \(\tau\)-framed tubular neighborhood.

\label{prop:standard-LMOV}
Let $f^{\vec\tau}_{\vec A}(q,a)$ be the reformulated colored invariants determined by
\begin{equation}\label{eq:standard-reformulated}
 \log Z^{\vec\tau}(x)
 =\sum_{d\ge1}\frac1d\sum_{\vec A\ne\vec\varnothing}
 f^{\vec\tau}_{\vec A}(q^d,a^d)
 \prod_{c=1}^{L}s_{A^c}\bigl((x^c)^d\bigr).
\end{equation}
For partitions $A,B$ of the same size define, in the present normalization,
\begin{equation}\label{eq:MAB}
 M_{AB}(q)=\sum_{\mu\vdash |A|}
 \frac{\chi_A(\mu)\chi_B(\mu)}{\mathfrak z_\mu}
 \prod_{i=1}^{\ell(\mu)}\{\mu_i\}.
\end{equation}
Then
\begin{equation}\label{eq:fMP}
 f^{\vec\tau}_{\vec A}(q,a)
 =\sum_{\vec B}P^{\vec\tau}_{\vec B}(q,a)
 \prod_{c=1}^{L}M_{A^cB^c}(q).
\end{equation}
Consequently, for $\vec\tau=0$, the coefficients $P^0_{\vec B}$ are exactly the standard LMOV reformulated invariants of \cite{LP} under the variable convention $q_{\mathrm{LP}}=q^{-2}$ and $t_{\mathrm{LP}}=a^{-2}$.

\label{lem:ordinary-connected}
For a framed oriented link with $h\ge1$ ordinary labeled components,
\begin{equation}\label{eq:ordinary-connected}
 \operatorname{Cum}(\mathcal{L})\in z^{h-2}\mathbb Z[v,a^{\pm1}].
\end{equation}

\label{prop:anchor}
For normalized colors $B_{m_1},\dots,B_{m_k}$ and $h\ge1$ ordinary labeled components,
\begin{equation}\label{eq:anchor}
 \operatorname{Cum}(B_{m_1},\dots,B_{m_k};h\text{ ordinary})
 \in\left(\prod_{i=1}^k\{m_i\}^2\right)z^{h-2}\mathbb Z[v,a^{\pm1}].
\end{equation}

\label{thm:gcd}
Let $\mathcal L$ have an arbitrary integer framing vector $\vec\tau$, and let $\vec\lambda$ be a nonempty cycle tuple with $r$ total parts and part-gcd $D=D_{\vec\lambda}$.  For the signed $q$-framed partition function,
\begin{equation}\label{eq:gcd}
 \check F^{\vec\tau}_{\vec\lambda}\in
 \frac{\{\vec\lambda\}^2}{\{D\}^2}\mathbb Z[v,a^{\pm1}],
 \qquad
 H^{\vec\tau}_{\vec\lambda}\in\mathbb Z[v,a^{\pm1}].
\end{equation}

\label{thm:relative-hecke}
For every $n\ge2$ and every $\alpha$ with $\operatorname{ord}(\alpha^2)=n$,
\begin{align}
 S_n&\in[A,\mathsf{G}]+\{n\}^2\mathsf{G},\label{eq:self-main}\\
 M_n&\in[A,\mathsf{G}]+\{n\}^4\mathsf{G}.\label{eq:mixed-main}
\end{align}

\label{lem:root-framing}
If $\operatorname{ord}(\alpha^2)=n$ and $\varepsilon_n=(-1)^{n-1}$, then for every integer $\tau$,
\begin{equation}\label{eq:root-framing}
 \check Z_n(K;\tau)
 \equiv a^{n\tau}\varepsilon_n^{\tau}\check Z_n(K;0)
 \pmod{(q-\alpha)^2}.
\end{equation}

\label{lem:smoothing-framing}
Let $c$ be a crossing of sign $\sigma(c)\in\{\pm1\}$ in an oriented framed diagram,
and give the oriented smoothing the inherited ribbon framing.
\begin{enumerate}[label=(\roman*)]
\item If $c$ is a mixed crossing between distinct components $K_i,K_j$ with framings
$\tau_i,\tau_j$, the smoothing merges them into $K_{ij}$ and
\begin{equation}\label{eq:mixed-smoothing-framing}
 \tau(K_{ij})=\tau_i+\tau_j+2\operatorname{lk}(K_i,K_j)-\sigma(c),
\end{equation}
so
\begin{equation}\label{eq:mixed-smoothing-parity}
 \tau(K_{ij})\equiv\tau_i+\tau_j+1\pmod2.
\end{equation}
\item If $c$ is a self-crossing of $K$ and the smoothing splits it into $K',K''$, then
\begin{equation}\label{eq:self-smoothing-framing}
 \tau(K)=\tau(K')+\tau(K'')+2\operatorname{lk}(K',K'')+\sigma(c),
\end{equation}
and hence
\begin{equation}\label{eq:self-smoothing-parity}
 \tau(K)\equiv\tau(K')+\tau(K'')+1\pmod2.
\end{equation}
\end{enumerate}
Thus every oriented smoothing changes the parity of the sum of the individual framings by
exactly one.

\label{prop:uniform-knot}
If $\operatorname{ord}(\alpha^2)=n$, then every framed knot $(K,\tau)$ satisfies
\begin{equation}\label{eq:uniform-knot}
 \check Z_n(K;\tau)
 \equiv\varepsilon_n^\tau\Psi_n\check Z_1(K;\tau)
 \pmod{(q-\alpha)^2}.
\end{equation}

\label{thm:equal-cycle}
Let $\mathcal L$ be a framed link with $r\ge1$ labeled components, each carrying $B_n$, and put
$\tau(\mathcal L)=\sum_i\tau(K_i)$.  If $\operatorname{ord}(\alpha^2)=n$, then
\begin{equation}\label{eq:equal-cycle}
 H^{\mathrm{ord}}_{(n^r)}(\mathcal L)
 \equiv n^{r-1}\varepsilon_n^{\tau(\mathcal L)}
 \Psi_nH^{\mathrm{ord}}_{(1^r)}(\mathcal L)
 \pmod{(q-\alpha)^2}.
\end{equation}

\label{lem:cable-cycle}
For every $m\ge1$,
\begin{equation}\label{eq:cable-cycle}
 \check Z_{mD}\!\left(K;\frac{k}{D}\right)
 =\frac{\{mD\}}{\{m\}}\check Z_m(J;kD).
\end{equation}

\label{lem:finite-slope}
Fix $m,D_1,\ldots,D_r$ and the zero-individually-framed labeled link $\mathcal{L}$.  There are a
finite index set $\mathcal I$ and coefficients $R_I(q,a)$, independent of the slopes
$k_1,\ldots,k_r$, such that
\begin{equation}\label{eq:finite-slope}
 H^{\mathrm{ord}}_{(mD_i)}\!\left(\mathcal{L};\frac{k_i}{D_i}\right)
 =a^{m\sum_i k_i}\sum_{I\in\mathcal I}R_I(q,a)
 q^{\sum_i k_i\kappa_{A_i(I)}/D_i}.
\end{equation}
Every exponent $\kappa_{A_i(I)}/D_i$ occurring in a nonzero term is an integer.

\label{lem:hook-root-phase}
Let $\operatorname{ord}(\alpha^2)=n$ and $\omega=\alpha^n\in\{\pm1\}$.  For a hook
$A=(nD-b,1^b)$ and a hook $B=(D-c,1^c)$,
\begin{align}
 \alpha^{k\kappa_A/D}&=\omega^{k(nD-1)},\label{eq:upper-hook-phase}\\
 \alpha^{nk\kappa_B/D}&=\omega^{k(D-1)},\label{eq:lower-hook-phase}
\end{align}
independently of $b,c$, and
\begin{equation}\label{eq:phase-ratio}
 \omega^{k(nD-1)}=\varepsilon_n^{kD}\omega^{k(D-1)}.
\end{equation}

\label{thm:universal-slope}
Let $D_1,\ldots,D_r$ be positive integers.  Fix $n\ge2$ and
$\operatorname{ord}(\alpha^2)=n$.  For every integer vector $(k_1,\ldots,k_r)$,
\begin{equation}\label{eq:universal-slope}
 H^{\mathrm{ord}}_{(nD_i)}\!\left(\mathcal{L};\frac{k_i}{D_i}\right)
 \equiv n^{r-1}\varepsilon_n^{\sum_i k_iD_i}
 \Psi_nH^{\mathrm{ord}}_{(D_i)}\!\left(\mathcal{L};\frac{k_i}{D_i}\right)
 \pmod{(q-\alpha)^2}.
\end{equation}

Fix a nonempty partition tuple $\vec\lambda$ with $D=D_{\vec\lambda}$ and $r=\ell(\vec\lambda)$.  By Theorem~\ref{thm:gcd}, every $H^{\vec\tau}_{\vec\rho}$ belongs to $\mathbb Z[v,a^{\pm1}]$.  By \eqref{eq:intro-key-normalization}, it is enough to prove
\begin{equation}\label{eq:mobius-div}
 U_D(v)\ \Bigm|\
 \sum_{k\mid D}\mu(k)k^{r-1}\Psi_kH^{\vec\tau}_{\vec\lambda/k}
 \qquad\text{in }\mathbb Q[v,a^{\pm1}].
\end{equation}

Fix $e\mid D$ ($e>1$) with $\operatorname{rad}(e)=\prod_{p\mid e}p$, and let $\alpha$ satisfy $\operatorname{ord}(\alpha^2)=e$.  Only squarefree divisors contribute to the sum in \eqref{eq:mobius-div} since $\mu(k)=0$ unless $k$ is squarefree.  Write such a divisor uniquely as
\[
 k=d\ell,\qquad d\mid\operatorname{rad}(e),\qquad (\ell,e)=1.
\]

By the following Lemma \ref{lem:Mobius-term-reduction}, which is an easy consequence of Theorem~\ref{thm:framed-congruence}, we obtain 

\[
 \Psi_{d\ell}H^{\vec\tau}_{\vec\lambda/(d\ell)}
 \equiv (e/d)^{r-1}\Psi_{e\ell}H^{\vec\tau}_{\vec\lambda/(e\ell)}
 \pmod{(q-\alpha)^2}.
\]

 Multiplication by $\mu(d \ell)(d\ell)^{r-1}$ gives
\[
\begin{aligned}
&
\mu(d\ell)
(d\ell)^{r-1}
\Psi_{d\ell}
H_{\vec\lambda/(d\ell)}^{\vec\tau}
\\
&\qquad\equiv
\mu(d)\mu(\ell)
(d\ell)^{r-1}
\left(\frac{e}{d}\right)^{r-1}
\Psi_{e\ell}
H_{\vec\lambda/(e\ell)}^{\vec\tau}
\\
&\qquad=
\mu(d)\,
\mu(\ell)
(e\ell)^{r-1}
\Psi_{e\ell}
H_{\vec\lambda/(e\ell)}^{\vec\tau}
\pmod{(q-\alpha)^2}.
\end{aligned}
\]
Therefore, we have 
\[
\begin{aligned}
&
\sum_{d\mid\operatorname{rad}(e)}
\mu(d\ell)
(d\ell)^{r-1}
\Psi_{d\ell}
H_{\vec\lambda/(d\ell)}^{\vec\tau}
\\
&\qquad\equiv
\mu(\ell)
(e\ell)^{r-1}
\Psi_{e\ell}
H_{\vec\lambda/(e\ell)}^{\vec\tau}
\sum_{d\mid\operatorname{rad}(e)}
\mu(d)
\\
&\qquad=0
\pmod{(q-\alpha)^2}
\end{aligned}
\]
since $
 \sum_{d\mid\operatorname{rad}(e)}\mu(d)=0$ for $e>1$.  Thus the sum in \eqref{eq:mobius-div} vanishes to second order at every root of exact squared order $e\mid D$, $e>1$.


We now translate the second-order vanishing in $q$ into polynomial
divisibility in $v=(q-q^{-1})^2.$  For $e>2$, the map $q\mapsto v$ is unramified and therefore the corresponding root in the $v$-variable occurs with multiplicity two. For $e=2$, $v+4=(q+q^{-1})^2$, so second-order vanishing in $q-\alpha$ gives one factor $v+4$.  These are exactly the multiplicities in the monic polynomial $U_D(v)$, we obtain \eqref{eq:mobius-div}.  


By formula \eqref{eq:intro-key-normalization}, we have
\[
 vC^{\vec\tau}_{\vec\lambda}\in\mathbb Q[v,a^{\pm1}].
\]
Hence
\[
vP_{\vec A}^{\vec\tau}
=
\sum_{\vec\lambda}
\chi_{\vec A}(\vec\lambda)
vC_{\vec\lambda}^{\vec\tau}
\in
\mathbb Q[v,a^{\pm1}].
\]

\label{lem:Mobius-term-reduction}
Let $\vec\lambda$ be a nonempty partition tuple, put $D=D_{\vec\lambda}$ and $r=\ell(\vec\lambda)$, and let $e>1$ divide $D$. Let $\alpha$ satisfy $\operatorname{ord}(\alpha^2)=e$ and set
\[
k=d\ell,
\qquad
d\mid\operatorname{rad}(e),
\qquad
(\ell,e)=1,\qquad \ell\mid D.
\]
Then
\begin{equation}
\label{eq:Mobius-term-local-comparison}
\Psi_{d\ell}
H_{\vec\lambda/(d\ell)}^{\vec\tau}
\equiv
\left(\frac{e}{d}\right)^{r-1}
\Psi_{e\ell}
H_{\vec\lambda/(e\ell)}^{\vec\tau}
\pmod{(q-\alpha)^2}.
\end{equation}
Note that this formula holds tautologically for $e/d=1$.

\label{lem:invariant-localization}
Let $G$ be the group generated by the involutions $q\mapsto -q$ and $q\mapsto q^{-1}$, both fixing $a$.  Then
\begin{equation}\label{eq:invariant-localization}
 R_0^G
 =\mathbb Z[v,a^{\pm1},\{m\}^{-2}:m\ge1]
 =\mathbb Z[v,a^{\pm1},(vU_m(v))^{-1}:m\ge1].
\end{equation}

\label{lem:primitive-symmetry}
Let $Y_q$ denote the divided alphabet, $p_m(Y_q)=p_m(y)/\{m\}_q$.  For every integer framing vector $\vec\tau$,
\begin{equation}\label{eq:partition-symmetry}
 Z^{\vec\tau}[Y_{q}]|_{q\rightarrow -q}=Z^{\vec\tau}[Y_q],
 \qquad
 Z^{\vec\tau}[Y_{q}]|_{q\rightarrow q^{-1}}=Z^{\vec\tau}[Y_q].
\end{equation}
Consequently
\begin{equation}\label{eq:plog-symmetry}
 \operatorname{PLog}Z^{\vec\tau}[Y_q]|_{q\rightarrow -q}
 =\operatorname{PLog}Z^{\vec\tau}[Y_q],
 \qquad
 \operatorname{PLog}Z^{\vec\tau}[Y_q]|_{q\rightarrow q^{-1}}
 =\operatorname{PLog}Z^{\vec\tau}[Y_q],
\end{equation}
and every primitive Schur coefficient $P_{\vec A}^{\vec\tau}$ is fixed by both involutions.

\label{prop:localization}
For every oriented link, integer framing vector $\vec\tau$, and
tuple $\vec A$, the signed Schur coefficient invariants satisfies
\begin{equation}\label{eq:arith-localization}
 P_{\vec A}^{\vec\tau}
       \in\mathbb Z[v,a^{\pm1},\{m\}^{-2}:m\ge1].
\end{equation}

\label{lem:full-grid}
There is an exact identity over $\mathbb Z[z]$
\begin{equation}\label{eq:full-grid}
 C^2=\sum_{k=0}^nz^kR_k.
\end{equation}
Each $R_k$ commutes with $A$, $R_0=1$, and
\begin{equation}\label{eq:top-grid}
 R_n=\Omega_{\mathsf{H}}C,
 \qquad
 \Omega_{\mathsf{H}}=\sum_{w\in S_n}T_{w,L}T_{w^{-1},R}.
\end{equation}

\label{lem:shuffle}
All factors in
\begin{equation}\label{eq:shuffle}
 R_k=\sum_{x\in\mathcal D_k}T_x\Delta_kT_{x^{-1}}
\end{equation}
are length-additive, and $\Delta_k$ commutes with $B_k$.

\label{lem:transported-higman-square}
Let
\[
 \theta(g_i)=-g_i^{-1}=z-g_i,
 \qquad t_{\mathsf{H}}^-:=t_{\mathsf{H}}\circ\theta,
\]
and let $h_{\mathsf{H}}^-$ be the Higman map defined by the transported symmetrizing trace $t_{\mathsf{H}}^-$.  Then
\begin{equation}\label{eq:transported-higman-square}
 h_{\mathsf{H}}^-(b_n)\in\{n\}^2\mathsf{H}.
\end{equation}
More precisely, over the generic split semisimple field,
\begin{equation}\label{eq:transported-higman-hooks}
 z^n h_{\mathsf{H}}^-(b_n)
 =\{n\}^2\sum_{j=0}^{n-1}(-1)^j c_j^-p_j,
 \qquad
 c_j^-=q^{-\kappa_j/2}\{n-j-1\}!\{j\}!.
\end{equation}
If $B\subset \mathsf{H}$ is a proper standard Young subalgebra preserved by $\theta$ and $\mathcal D$ is the usual set of distinguished coset representatives, define the transported norm
\begin{equation}\label{eq:transported-norm}
 N_{B}^{\mathsf{H},-}(y)
 :=\sum_{x\in\mathcal D}\theta(T_{x^{-1}})\,y\,\theta(T_x).
\end{equation}
Then
\begin{equation}\label{eq:transported-transitivity}
 h_B^-N_B^{\mathsf{H},-}=h_{\mathsf{H}}^-,
\end{equation}
and consequently
\begin{equation}\label{eq:transported-norm-div}
 N_B^{\mathsf{H},-}(b_n)\in[B,\mathsf{H}]+\{n\}^2\mathsf{H}.
\end{equation}

\label{lem:self-proper}
For $0<k<n$, the formula
\begin{equation}\label{eq:self-transfer-map}
 \begin{aligned}
 S_k&:\mathsf{H}/[B_R,\mathsf{H}]\longrightarrow M_k/[A,M_k],\\
 S_k([h])&=\sum_{x_L\in\mathcal D_L}[h_LE_{x_L,k}]
 \end{aligned}
\end{equation}
defines an $R_\alpha$-linear map. The analogous right-handed
map, with $B_L$ and $\mathcal D_R$, is also well defined.
Moreover, if
\begin{equation}\label{eq:self-transported-norm}
 N_{B_k}^{A,-}(y)=\sum_{x\in\mathcal D_k}
                 \theta(T_{x^{-1}})y\theta(T_x),
\end{equation}
then
\begin{equation}\label{eq:self-norm-square}
 N_{B_k}^{A,-}(b_LC)\in[B_k,\mathsf{G}]+\{n\}^2\mathsf{G},
\end{equation}
and
\begin{equation}\label{eq:self-proper-divisibility}
 b_LC\theta(R_k)\in[A,\mathsf{G}]+\{n\}^2\mathsf{G}.
\end{equation}
